package com.aurasound.next;
import android.app.Activity;import android.os.Bundle;import android.os.Build;import android.Manifest;import android.content.pm.PackageManager;import android.content.Intent;import android.net.Uri;import android.provider.MediaStore;import android.database.Cursor;import android.webkit.*;import android.widget.Toast;import org.json.JSONArray;import org.json.JSONObject;
public class MainActivity extends Activity{
 private WebView webView;private ValueCallback<Uri[]> fileCallback;private boolean pageReady=false;private static final int FILE_PICKER=4102,AUDIO_PERMISSION=4103;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(android.graphics.Color.rgb(3,7,18));getWindow().setNavigationBarColor(android.graphics.Color.rgb(3,7,18));webView=new WebView(this);webView.setBackgroundColor(android.graphics.Color.rgb(3,7,18));WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setAllowFileAccess(true);s.setAllowContentAccess(true);
 webView.addJavascriptInterface(new Object(){@JavascriptInterface public String getAudioTracks(){return queryAudioTracks();}@JavascriptInterface public void shareTrack(String title,String uri){runOnUiThread(()->{try{Intent i=new Intent(Intent.ACTION_SEND);i.setType("audio/*");i.putExtra(Intent.EXTRA_STREAM,Uri.parse(uri));i.putExtra(Intent.EXTRA_SUBJECT,title);i.putExtra(Intent.EXTRA_TEXT,title);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"اشتراک‌گذاری آهنگ"));}catch(Exception e){Toast.makeText(MainActivity.this,"اشتراک‌گذاری ممکن نیست",Toast.LENGTH_SHORT).show();}});}},"AuraNative");
 webView.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=cb;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("audio/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,FILE_PICKER);return true;}});webView.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView view,String url){pageReady=true;if(hasPermission())sendTracks();else requestAudioPermission();}});setContentView(webView);webView.loadUrl("file:///android_asset/index.html");}
 private boolean hasPermission(){if(Build.VERSION.SDK_INT>=33)return checkSelfPermission(Manifest.permission.READ_MEDIA_AUDIO)==PackageManager.PERMISSION_GRANTED;return Build.VERSION.SDK_INT<23||checkSelfPermission(Manifest.permission.READ_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED;}
 private void requestAudioPermission(){if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{Manifest.permission.READ_MEDIA_AUDIO},AUDIO_PERMISSION);else if(Build.VERSION.SDK_INT>=23)requestPermissions(new String[]{Manifest.permission.READ_EXTERNAL_STORAGE},AUDIO_PERMISSION);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==AUDIO_PERMISSION){if(hasPermission())sendTracks();else Toast.makeText(this,"برای یافتن آهنگ‌ها، دسترسی موسیقی را از تنظیمات برنامه فعال کنید.",Toast.LENGTH_LONG).show();}}
 private String queryAudioTracks(){JSONArray a=new JSONArray();if(!hasPermission())return a.toString();String[] cols={MediaStore.Audio.Media._ID,MediaStore.Audio.Media.TITLE,MediaStore.Audio.Media.ARTIST,MediaStore.Audio.Media.ALBUM,MediaStore.Audio.Media.SIZE,MediaStore.Audio.Media.DATE_ADDED};try(Cursor c=getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,cols,MediaStore.Audio.Media.IS_MUSIC+" != 0",null,MediaStore.Audio.Media.TITLE+" COLLATE NOCASE ASC")){if(c!=null)while(c.moveToNext()){JSONObject o=new JSONObject();long id=c.getLong(0);o.put("url",Uri.withAppendedPath(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,String.valueOf(id)).toString());o.put("name",c.getString(1)==null?"بدون نام":c.getString(1));o.put("artist",c.getString(2)==null?"ناشناخته":c.getString(2));o.put("album",c.getString(3)==null?"حافظه دستگاه":c.getString(3));o.put("size",c.getLong(4));o.put("date",c.getLong(5)*1000);a.put(o);}}catch(Exception ignored){}return a.toString();}
 private void sendTracks(){if(webView!=null&&pageReady)webView.post(()->webView.evaluateJavascript("window.loadNativeTracks && window.loadNativeTracks("+queryAudioTracks()+")",null));}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==FILE_PICKER&&fileCallback!=null){Uri[] out=null;if(c==RESULT_OK&&d!=null){if(d.getClipData()!=null){int n=d.getClipData().getItemCount();out=new Uri[n];for(int x=0;x<n;x++)out[x]=d.getClipData().getItemAt(x).getUri();}else if(d.getData()!=null)out=new Uri[]{d.getData()};}fileCallback.onReceiveValue(out);fileCallback=null;}}
 @Override protected void onResume(){super.onResume();if(hasPermission())sendTracks();}
 @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}
}